<script module>  export const manifiesto = {    id: 'contabilidad',    nombre: 'Contabilidad',    icono: 'book',    grupo: 'utilidades',    orden: 11,    tablas: {},  };</script><script>  import { onMount } from 'svelte';  import { listar, leerConfig } from '../../core/db.js';  import { bus } from '../../core/bus.js';  import { n, fmt, nowLocal } from '../../core/util.js';  import { libroDiario, estadoPyG, balanceGeneral } from '../../core/contabilidad.js';  import Icono from '../../core/Icono.svelte';  let cfg = $state({});  let ventas = $state([]);  let compras = $state([]);  let retiros = $state([]);  let capital = $state([]);  let ajustes = $state([]);  let lotes = $state([]);  let cierres = $state([]);  let gastosOp = $state([]);  let movCaja = $state([]);  let fechaInicio = $state(nowLocal().local.slice(0, 8) + '01');  let fechaFin = $state(nowLocal().local);  let tab = $state('diario');  let paginaDiario = $state(1);  const itemsPorPagina = 50;  const diario = $derived(libroDiario({ ventas, compras, retiros, capital, gastosOp, ajustes }, fechaInicio, fechaFin));  const totalPaginasDiario = $derived(Math.max(1, Math.ceil(diario.length / itemsPorPagina)));  const diarioPaginado = $derived(diario.slice((paginaDiario - 1) * itemsPorPagina, paginaDiario * itemsPorPagina));  const pyg = $derived(estadoPyG({ ventas, compras, ajustes, gastosOp }, fechaInicio, fechaFin));  const balance = $derived(balanceGeneral({ cfg, capital, retiros, ventas, compras, lotes, cierres, movCaja, ajustes }));  async function recargar() {    [ventas, compras, retiros, capital, ajustes, lotes, cierres, gastosOp, movCaja] = await Promise.all([      listar('ventas'), listar('compras'), listar('retiros'), listar('capital'),      listar('ajustes'), listar('lotes'), listar('cierres'), listar('gastosOp'), listar('movCaja')    ]);    cfg = (await leerConfig('cfg')) || {};  }  onMount(() => {    recargar();    const off = bus.on('recargar', recargar);    return () => off();  });</script><div class='modulo'>  <div class='bg-card rounded-[var(--radius-lg)] p-4 shadow-[var(--color-shadow)] mb-3'>    <!-- Tabs mejorados -->    <div class='flex gap-1 bg-background rounded-xl p-1 mb-4'>      <button class='flex-1 py-2.5 rounded-lg text-xs font-bold transition-all {tab === 'diario' ? 'bg-primary text-white shadow-sm' : 'text-muted'}' onclick={() => { tab = 'diario'; paginaDiario = 1; }}>Libro Diario</button>      <button class='flex-1 py-2.5 rounded-lg text-xs font-bold transition-all {tab === 'pyg' ? 'bg-primary text-white shadow-sm' : 'text-muted'}' onclick={() => tab = 'pyg'}>P&L</button>      <button class='flex-1 py-2.5 rounded-lg text-xs font-bold transition-all {tab === 'balance' ? 'bg-primary text-white shadow-sm' : 'text-muted'}' onclick={() => tab = 'balance'}>Balance</button>    </div>    {#if tab !== 'balance'}      <div class='grid grid-cols-2 gap-2 mb-4'>        <input type='date' class='px-3 py-2.5 border border-border rounded-lg bg-card text-sm outline-none focus:border-primary' bind:value={fechaInicio} />        <input type='date' class='px-3 py-2.5 border border-border rounded-lg bg-card text-sm outline-none focus:border-primary' bind:value={fechaFin} />      </div>    {/if}    {#if tab === 'diario'}      {#if diario.length === 0}        <div class='text-center text-muted py-8 text-sm'>Sin movimientos en el periodo</div>      {:else}        <div class='overflow-x-auto'>          <table class='w-full text-sm'>            <thead><tr class='text-left text-muted border-b border-border'><th class='pb-2'>Fecha</th><th class='pb-2'>Cuenta</th><th class='pb-2 text-right'>Debe</th><th class='pb-2 text-right'>Haber</th></tr></thead>            <tbody>              {#each diarioPaginado as m}                <tr class='border-b border-border/50'>                  <td class='py-2 text-xs text-muted'>{new Date(m.fecha).toLocaleDateString()}</td>                  <td class='py-2 font-medium'>{m.cuenta}</td>                  <td class='py-2 text-right text-danger font-bold'>{m.debe > 0 ? fmt(m.debe) : ''}</td>                  <td class='py-2 text-right text-success font-bold'>{m.haber > 0 ? fmt(m.haber) : ''}</td>                </tr>              {/each}            </tbody>          </table>        </div>        {#if totalPaginasDiario > 1}          <div class='flex items-center justify-center gap-2 mt-3'>            <button class='w-9 h-9 rounded-lg bg-background border border-border flex items-center justify-center disabled:opacity-30 active:scale-[0.95] transition-transform' onclick={() => (paginaDiario = Math.max(1, paginaDiario - 1))} disabled={paginaDiario === 1} aria-label='Pagina anterior'><Icono nombre='chevron' size={14} class='rotate-90' /></button>            <span class='text-xs text-muted font-bold px-2'>{paginaDiario} / {totalPaginasDiario}</span>            <button class='w-9 h-9 rounded-lg bg-background border border-border flex items-center justify-center disabled:opacity-30 active:scale-[0.95] transition-transform' onclick={() => (paginaDiario = Math.min(totalPaginasDiario, paginaDiario + 1))} disabled={paginaDiario === totalPaginasDiario} aria-label='Pagina siguiente'><Icono nombre='chevron' size={14} class='-rotate-90' /></button>          </div>        {/if}      {/if}    {:else if tab === 'pyg'}      <div class='space-y-1'>        <div class='flex justify-between items-center py-2.5 border-b border-border text-sm'>          <div class='flex items-center gap-2'><div class='w-2 h-2 rounded-full bg-success'></div><span>Ingresos</span></div>          <span class='text-success font-bold'>{fmt(pyg.ingresos)}</span>        </div>        <div class='flex justify-between items-center py-2.5 border-b border-border text-sm'>          <div class='flex items-center gap-2'><div class='w-2 h-2 rounded-full bg-danger'></div><span>Costo de bienes</span></div>          <span class='text-danger font-bold'>-{fmt(pyg.cogs)}</span>        </div>        <div class='flex justify-between items-center py-2.5 border-b border-border text-sm font-bold bg-primary/5 rounded-lg px-3'>          <span>Ganancia bruta</span>          <span class='text-primary'>{fmt(pyg.gananciaBruta)}</span>        </div>        <div class='flex justify-between items-center py-2.5 border-b border-border text-sm'>          <div class='flex items-center gap-2'><div class='w-2 h-2 rounded-full bg-danger'></div><span>Mermas</span></div>          <span class='text-danger font-bold'>-{fmt(pyg.mermas)}</span>        </div>        <div class='flex justify-between items-center py-2.5 border-b border-border text-sm'>          <div class='flex items-center gap-2'><div class='w-2 h-2 rounded-full bg-danger'></div><span>Gastos operativos</span></div>          <span class='text-danger font-bold'>-{fmt(pyg.gastosOperativos)}</span>        </div>        <div class='flex justify-between items-center py-3 bg-success/10 rounded-xl px-3 font-extrabold text-success'>          <span>GANANCIA NETA</span>          <span>{fmt(pyg.gananciaNeta)}</span>        </div>      </div>    {:else}      <div class='space-y-4'>        <div>          <h3 class='font-bold text-primary mb-2 flex items-center gap-2'><div class='w-2 h-2 rounded-full bg-primary'></div>Activos</h3>          <div class='flex justify-between items-center py-2 text-sm'><span>Caja / Bancos</span><span class='font-bold'>{fmt(balance.activos.caja)}</span></div>          <div class='flex justify-between items-center py-2 text-sm'><span>Inventario</span><span class='font-bold'>{fmt(balance.activos.inventario)}</span></div>          <div class='flex justify-between items-center py-2 border-t border-border font-bold bg-primary/5 rounded-lg px-3 mt-1'>            <span>Total activos</span>            <span class='text-primary'>{fmt(balance.activos.total)}</span>          </div>        </div>        <div>          <h3 class='font-bold text-purple mb-2 flex items-center gap-2'><div class='w-2 h-2 rounded-full bg-purple'></div>Patrimonio</h3>          <div class='flex justify-between items-center py-2 text-sm'><span>Capital social</span><span class='font-bold'>{fmt(balance.patrimonio.capital)}</span></div>          <div class='flex justify-between items-center py-2 text-sm'><span>Ganancias retenidas</span><span class='font-bold'>{fmt(balance.patrimonio.gananciasRetenidas)}</span></div>          <div class='flex justify-between items-center py-2 border-t border-border font-bold bg-purple/5 rounded-lg px-3 mt-1'>            <span>Total patrimonio</span>            <span class='text-purple'>{fmt(balance.patrimonio.total)}</span>          </div>        </div>      </div>    {/if}  </div></div>